-- 全国行政区划地址表（自动生成，非官方区县名，测试占位）
DROP TABLE IF EXISTS tb_address;
CREATE TABLE tb_address (
  id BIGINT NOT NULL AUTO_INCREMENT,
  name VARCHAR(64) NOT NULL COMMENT '本级名称：广东省/深圳市/南山区',
  level TINYINT NOT NULL COMMENT '1省 2市 3区县',
  parent_id BIGINT DEFAULT NULL COMMENT '上级id（省级为NULL）',
  code CHAR(6) DEFAULT NULL COMMENT '行政区划代码（近似）',
  province VARCHAR(64) NOT NULL COMMENT '省名（冗余，便于join）',
  city VARCHAR(64) DEFAULT NULL COMMENT '市名',
  district VARCHAR(64) DEFAULT NULL COMMENT '区县名',
  full_name VARCHAR(192) NOT NULL COMMENT '完整地址',
  lng DECIMAL(10,6) NOT NULL COMMENT '中心经度（近似）',
  lat DECIMAL(10,6) NOT NULL COMMENT '中心纬度（近似）',
  PRIMARY KEY (id),
  KEY idx_parent (parent_id),
  KEY idx_level (level),
  KEY idx_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='全国行政区划地址表';

